    # This set is used to track the numbers that we have processed
    visited = set()

    def can_divide(n):
        return n % 2 == 0

    def can_multiply(n):
        return (n * 3) % 2 == 1

    def process(num):
        # Using a set to track visited numbers to avoid infinite loop
        while num in visited:
            return operations_count
        visited.add(num)
        nonlocal operations_count
        operations_count += 1
        new_numbers = []

        if can_divide(num):
            new_numbers.append(num // 2)
        if can_multiply(num):
            new_numbers.append(num * 3)

        for new_num in new_numbers:
            process(new_num)

    for number in a:
        process(number)

    print(operations_count)

